  ('fg-g00678', 'forest-governance', 'policy-and-administration', 'Medium', 'mock',
   'What is a primary purpose of the Buffer Zone Management Policy under the National Integrated Protected Areas System (NIPAS)?',
   '[{"id":"a","text":"To increase agricultural production in rural areas"},{"id":"b","text":"To facilitate commercial logging operations"},{"id":"c","text":"To promote urban development"},{"id":"d","text":"To minimize the impact of human activities on protected areas"}]'::jsonb, 'd'),
  ('fg-g00679', 'forest-governance', 'policy-and-administration', 'Medium', 'mock',
   'Under Republic Act No. 8371, which key aspect is vital for the issuance of a Certificate of Ancestral Domain Title (CADT)?',
   '[{"id":"a","text":"Historical and cultural evidence of indigenous occupation"},{"id":"b","text":"Presence of mineral resources"},{"id":"c","text":"Potential for tourism development"},{"id":"d","text":"Availability of infrastructure"}]'::jsonb, 'a'),
  ('fg-g00680', 'forest-governance', 'policy-and-administration', 'Medium', 'mock',
   'Which principle is emphasized in the implementation of the Community-Based Forest Management Program (CBFMP) as per Philippine forestry governance?',
   '[{"id":"a","text":"Exclusive use of local community resources"},{"id":"b","text":"Prioritization of commercial interests"},{"id":"c","text":"Restriction of indigenous peoples'' access"},{"id":"d","text":"Equitable access and sustainable management of forest resources"}]'::jsonb, 'd'),
  ('fg-g00681', 'forest-governance', 'policy-and-administration', 'Medium', 'mock',
   'What is the role of the National Commission on Indigenous Peoples (NCIP) in the context of forest lands?',
   '[{"id":"a","text":"To protect the rights and welfare of indigenous peoples regarding their ancestral domains"},{"id":"b","text":"To manage commercial logging permits"},{"id":"c","text":"To oversee the implementation of the National Greening Program"},{"id":"d","text":"To regulate the issuance of Environmental Compliance Certificates"}]'::jsonb, 'a'),
  ('fg-g00682', 'forest-governance', 'policy-and-administration', 'Medium', 'mock',
   'In the context of Philippine forestry governance, which of the following is a primary feature of a Community-Based Forest Management Agreement (CBFMA)?',
   '[{"id":"a","text":"It involves local communities in the sustainable management of forest resources."},{"id":"b","text":"It grants full ownership of forest lands to private corporations."},{"id":"c","text":"It allows unlimited commercial logging activities without restrictions."},{"id":"d","text":"It exempts all forest lands from environmental regulations."}]'::jsonb, 'a'),
  ('fg-g00683', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Under RA 8371, what is the critical distinction between a Certificate of Ancestral Domain Title (CADT) and a Certificate of Ancestral Land Title (CALT)?',
   '[{"id":"a","text":"CADT is granted indefinitely, whereas CALT has a renewable tenure of 25 years."},{"id":"b","text":"CADT includes rights to mineral resources, while CALT does not."},{"id":"c","text":"CADT covers larger territories and includes communal ownership, while CALT is individual and family-owned."},{"id":"d","text":"CADT is applicable only to agricultural lands, while CALT applies to forest lands."}]'::jsonb, 'c'),
  ('fg-g00684', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'In the context of Philippine forest policy, what is a fine legal requirement for converting an area classified under Protection Forests to Production Forests?',
   '[{"id":"a","text":"A comprehensive Environmental Impact Assessment and approval by the DENR Secretary."},{"id":"b","text":"A resolution from the local government and a public consultation process."},{"id":"c","text":"A Presidential Proclamation based on a recommendation from the DENR."},{"id":"d","text":"Approval from the National Commission on Indigenous Peoples and local government units."}]'::jsonb, 'c'),
  ('fg-g00685', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'When establishing a Community-Based Forest Management Agreement (CBFMA), what is a nuanced responsibility of the People''s Organization (PO) under DENR Administrative Order?',
   '[{"id":"a","text":"Ensure the establishment of a buffer zone around the community-managed area."},{"id":"b","text":"Secure funding from international NGOs for forest management activities."},{"id":"c","text":"Develop a comprehensive site development plan approved by the DENR."},{"id":"d","text":"Coordinate with the Philippine National Police for enforcement of forest laws."}]'::jsonb, 'c'),
  ('fg-g00686', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Under the National Integrated Protected Areas System (NIPAS) Act, what is a key procedural element in the establishment of a protected area management plan?',
   '[{"id":"a","text":"Sourcing funding from local government units before planning begins."},{"id":"b","text":"Obtaining consensus from all stakeholders through a national referendum."},{"id":"c","text":"Conducting a biodiversity assessment as part of the initial planning stage."},{"id":"d","text":"Securing a permit from the Department of Trade and Industry for any economic activities."}]'::jsonb, 'c'),
  ('fg-g00687', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'In the context of forest governance, which critical step must precede the issuance of an Integrated Forest Management Agreement (IFMA)?',
   '[{"id":"a","text":"Creation of a local forest management council to oversee operations."},{"id":"b","text":"Public bidding for private sector participation in forest exploitation."},{"id":"c","text":"Approval of a reforestation plan by the National Economic and Development Authority (NEDA)."},{"id":"d","text":"Environmental Compliance Certificate (ECC) approval after an Environmental Impact Assessment (EIA)."}]'::jsonb, 'd'),
  ('fg-g00688', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Which detailed legal criterion must be met to grant a Special Forest Land Use Agreement (FLAg) for ecotourism development in the Philippines?',
   '[{"id":"a","text":"The area must be less than 5 hectares and located outside protected areas."},{"id":"b","text":"The proposed project must align with a national tourism development plan."},{"id":"c","text":"The local community must receive 30% of the net income from ecotourism activities."},{"id":"d","text":"An Environmental Compliance Certificate must be obtained before application."}]'::jsonb, 'd'),
  ('fg-g00689', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'In ensuring compliance with the Indigenous Peoples'' Rights Act (IPRA), what is a subtle yet critical action required for projects affecting ancestral domains?',
   '[{"id":"a","text":"Submission of a Memorandum of Agreement (MOA) to the DENR for review."},{"id":"b","text":"Obtaining Free, Prior, and Informed Consent (FPIC) from the indigenous community."},{"id":"c","text":"Approval from the local government before project commencement."},{"id":"d","text":"Conducting a cultural impact assessment by an independent body."}]'::jsonb, 'b'),
  ('fg-g00690', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Considering the Revised Forestry Code (PD 705), what is a significant procedural requirement when classifying public lands as forest lands?',
   '[{"id":"a","text":"Public consultation with affected communities and stakeholders."},{"id":"b","text":"Completion of a cadastral survey and submission to the Land Management Bureau."},{"id":"c","text":"Approval from the Department of Agriculture after a technical assessment."},{"id":"d","text":"A recommendation from the Department of Trade and Industry based on land use potential."}]'::jsonb, 'b'),
  ('fg-g00691', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Under PD 705, what is a critical step in the process of classifying public lands as forest lands?',
   '[{"id":"a","text":"Conducting a land classification survey by the DENR."},{"id":"b","text":"Issuance of a Certificate of Land Classification Status by the NCIP."},{"id":"c","text":"Approval of the classification by the Department of Agrarian Reform."},{"id":"d","text":"Submission of classification proposal to the local government unit."}]'::jsonb, 'a'),
  ('fg-g00692', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'In the context of the National Greening Program (NGP), which step is crucial for ensuring sustainable forest management practices are implemented at the local level?',
   '[{"id":"a","text":"Mandatory approval from local business groups."},{"id":"b","text":"Direct oversight and management by the DENR Central Office."},{"id":"c","text":"Development of site-specific management plans by local stakeholders."},{"id":"d","text":"Exclusive reliance on national funding sources."}]'::jsonb, 'c'),
  ('fg-g00693', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'What is a nuanced requirement under the Indigenous Peoples'' Rights Act (IPRA) when projects are proposed in ancestral domains?',
   '[{"id":"a","text":"Issuance of a Special Use Permit by the DENR."},{"id":"b","text":"Obtaining Free and Prior Informed Consent (FPIC) from the affected indigenous community."},{"id":"c","text":"Securing a memorandum of agreement with local municipal governments."},{"id":"d","text":"Conducting an environmental impact assessment by independent third parties."}]'::jsonb, 'b'),
  ('fg-g00694', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Under the Expanded National Integrated Protected Areas System (E-NIPAS) Act, what is a key element in the preparation of a protected area management plan?',
   '[{"id":"a","text":"Setting up a community-based monitoring team."},{"id":"b","text":"Conducting a comprehensive biophysical and socio-economic assessment."},{"id":"c","text":"Establishing core zones within the protected area."},{"id":"d","text":"Developing tourism facilities before planning."}]'::jsonb, 'b'),
  ('fg-g00695', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Which specific legal criterion must be met to grant a Special Forest Land Use Agreement (FLAg) for ecotourism development in the Philippines?',
   '[{"id":"a","text":"Approval from the Department of Tourism only."},{"id":"b","text":"Certification from local business stakeholders."},{"id":"c","text":"Submission of a comprehensive site development plan including environmental safeguards."},{"id":"d","text":"Conducting a local plebiscite for project acceptance."}]'::jsonb, 'c'),
  ('fg-g00696', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Under the Community-Based Forest Management Agreement (CBFMA), what is a nuanced responsibility of the People''s Organization (PO) as outlined in DENR Administrative Orders?',
   '[{"id":"a","text":"Exclusive rights to commercial logging operations."},{"id":"b","text":"Submission of annual reports directly to the President."},{"id":"c","text":"Formation of a multi-sectoral monitoring team for project oversight."},{"id":"d","text":"Establishing independent partnerships with foreign investors."}]'::jsonb, 'c'),
  ('fg-g00697', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'What is a fine legal requirement for converting an area classified under Protection Forests to Production Forests in the Philippines?',
   '[{"id":"a","text":"Approval from the Council of Elders of local indigenous communities."},{"id":"b","text":"Authorization from the Department of Trade and Industry."},{"id":"c","text":"Completion of a comprehensive environmental and social impact assessment."},{"id":"d","text":"Consultation with local tourism boards."}]'::jsonb, 'c'),
  ('fg-g00698', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Considering the Revised Forestry Code (PD 705), what is a significant procedural requirement when classifying public lands?',
   '[{"id":"a","text":"Approval of classification by both the DENR and the Department of Agriculture."},{"id":"b","text":"Submission of a Technical Description of the land to the DENR."},{"id":"c","text":"Consultation with local government units for classification endorsement."},{"id":"d","text":"Completion of a socio-economic impact survey by external consultants."}]'::jsonb, 'b'),
  ('fg-g00699', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Under PD 705, what is a critical requirement for a forest land to be reclassified as alienable and disposable land?',
   '[{"id":"a","text":"Approval from the DENR Secretary after a comprehensive land use plan has been established."},{"id":"b","text":"A technical description of the land must be published in a local newspaper for at least three consecutive weeks."},{"id":"c","text":"An ordinance from the local government unit where the land is situated."},{"id":"d","text":"A presidential proclamation after thorough investigation and verification by the Forest Management Bureau."}]'::jsonb, 'd'),
  ('fg-g00700', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'In the Community-Based Forest Management Agreement (CBFMA), which of the following is a fundamental step required from the People''s Organization (PO) to ensure effective forest land management?',
   '[{"id":"a","text":"Submission of an Environmental Impact Assessment (EIA) to the DENR."},{"id":"b","text":"Conducting annual tree planting activities within the forest land."},{"id":"c","text":"Creation and implementation of a Community Resource Management Framework (CRMF)."},{"id":"d","text":"Securing a Certificate of Ancestral Domain Title (CADT) before any management activities."}]'::jsonb, 'c'),
  ('fg-g00701', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'What is a critical element required under RA 11038 (Expanded NIPAS Act) for the declaration of an area as a protected area?',
   '[{"id":"a","text":"A socio-economic survey of the indigenous communities in the area."},{"id":"b","text":"A commitment from local industries to fund conservation efforts."},{"id":"c","text":"A memorandum of understanding with local government units."},{"id":"d","text":"A comprehensive biodiversity assessment and mapping of the area."}]'::jsonb, 'd'),
  ('fg-g00702', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Under the Indigenous Peoples'' Rights Act (IPRA), what is a key requirement before implementing any project affecting ancestral domains?',
   '[{"id":"a","text":"Conducting a Free, Prior and Informed Consent (FPIC) process with the indigenous peoples."},{"id":"b","text":"Issuance of a Certificate of Ancestral Domain Title (CADT) to the affected community."},{"id":"c","text":"Establishing a trust fund for the community development projects."},{"id":"d","text":"Signing a memorandum of agreement between the project proponents and local government."}]'::jsonb, 'a'),
  ('fg-g00703', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'What is a fine distinction between a Certificate of Ancestral Domain Title (CADT) and a Certificate of Ancestral Land Title (CALT) under RA 8371?',
   '[{"id":"a","text":"A CADT encompasses entire ancestral domains, while a CALT pertains to specific lands within domains."},{"id":"b","text":"A CALT is solely issued to individuals, whereas a CADT is issued to communities."},{"id":"c","text":"A CADT requires approval from the NCIP, while a CALT is granted by the DENR."},{"id":"d","text":"A CALT is valid for agricultural lands, whereas a CADT is only for forest lands."}]'::jsonb, 'a'),
  ('fg-g00704', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'In the context of forest governance, what is a nuanced requirement under the Expanded National Integrated Protected Areas System (E-NIPAS) Act for developing a management plan for protected areas?',
   '[{"id":"a","text":"Coordination with international NGOs for technical assistance."},{"id":"b","text":"Integration of a climate change adaptation strategy within the plan."},{"id":"c","text":"Annual evaluation and revision of the management plan."},{"id":"d","text":"Establishment of a local tourism council to oversee protected area activities."}]'::jsonb, 'b'),
  ('fg-g00705', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'What is a significant procedural requirement under PD 705 for the classification of public lands as forest lands?',
   '[{"id":"a","text":"Conducting a cadastral survey to define the boundaries of the area."},{"id":"b","text":"Approval from the local government council through a resolution."},{"id":"c","text":"A land use feasibility study by an independent research institution."},{"id":"d","text":"A presidential proclamation based on technical evaluations by the DENR."}]'::jsonb, 'd'),
  ('fg-g00706', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'In the implementation of Republic Act No. 9147 (Wildlife Resources Conservation and Protection Act), what is a crucial requirement for the establishment of a wildlife sanctuary within forest lands?',
   '[{"id":"a","text":"Endorsement from the local government unit in the area."},{"id":"b","text":"Completion of a wildlife inventory and habitat assessment."},{"id":"c","text":"A public-private partnership agreement to manage the sanctuary."},{"id":"d","text":"A local ordinance declaring the area as a wildlife sanctuary."}]'::jsonb, 'b'),
  ('fg-g00707', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'What is a distinct characteristic of a Community-Based Forest Management Agreement (CBFMA) as compared to other forest land tenurial instruments in the Philippines?',
   '[{"id":"a","text":"It is the only tenurial instrument that requires an annual audit by the DENR."},{"id":"b","text":"It allows for the transfer of rights to another People''s Organization without DENR approval."},{"id":"c","text":"It includes a mandatory provision for livelihood projects for the community."},{"id":"d","text":"It provides a 25-year renewable term, contingent on performance evaluation."}]'::jsonb, 'd'),
  ('fg-g00708', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'What is a critical distinction between the National Integrated Protected Areas System (NIPAS) Act and the Expanded National Integrated Protected Areas System (E-NIPAS) Act with respect to buffer zone management?',
   '[{"id":"a","text":"NIPAS Act mandates community management of buffer zones, whereas E-NIPAS Act centralizes management under DENR."},{"id":"b","text":"NIPAS Act requires buffer zones only for terrestrial protected areas, while E-NIPAS Act extends this to marine areas."},{"id":"c","text":"NIPAS Act includes buffer zones as optional, while E-NIPAS Act mandates buffer zone establishment for all protected areas."},{"id":"d","text":"NIPAS Act allows for tourism development in buffer zones without restrictions, whereas E-NIPAS Act imposes strict ecological safeguards."}]'::jsonb, 'c'),
  ('fg-g00709', 'forest-governance', 'policy-and-administration', 'Hard', 'mock',
   'Under Republic Act No. 9147 (Wildlife Resources Conservation and Protection Act), what is a nuanced legal requirement for issuing permits for collecting wildlife species within CBFMA areas for scientific purposes?',
   '[{"id":"a","text":"The permit must be issued by the local government unit with territorial jurisdiction over the area."},{"id":"b","text":"The permit requires a separate Environmental Compliance Certificate (ECC) issued by the DENR regional office."},{"id":"c","text":"The permit can only be issued if the activity is part of a government-funded research project."},{"id":"d","text":"The permit requires prior informed consent from the relevant Indigenous Peoples'' communities, if applicable, even within CBFMA areas."}]'::jsonb, 'd'),
  ('fg-g00710', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'What is the primary objective of the Social Forestry program in the Philippines?',
   '[{"id":"a","text":"To increase the national GDP through timber sales."},{"id":"b","text":"To promote sustainable forest management through community involvement."},{"id":"c","text":"To export raw timber to international markets."},{"id":"d","text":"To restrict all access to forest resources."}]'::jsonb, 'b'),
  ('fg-g00711', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'Which law in the Philippines established the Community-Based Forest Management Strategy (CBFM)?',
   '[{"id":"a","text":"Republic Act 7586"},{"id":"b","text":"Executive Order 263"},{"id":"c","text":"Presidential Decree 705"},{"id":"d","text":"Republic Act 9147"}]'::jsonb, 'b'),
  ('fg-g00712', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'Which document grants indigenous peoples the rights to manage their ancestral domains under Philippine law?',
   '[{"id":"a","text":"Certificate of Land Ownership Award (CLOA)"},{"id":"b","text":"Certificate of Ancestral Domain Title (CADT)"},{"id":"c","text":"Community-Based Forest Management Agreement (CBFMA)"},{"id":"d","text":"Forest Land Use Plan (FLUP)"}]'::jsonb, 'b'),
  ('fg-g00713', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'In social forestry, what is a primary function of extension services?',
   '[{"id":"a","text":"To conduct scientific research independently from communities."},{"id":"b","text":"To enforce logging bans in protected areas."},{"id":"c","text":"To facilitate knowledge transfer and build capacity within communities."},{"id":"d","text":"To monitor wildlife populations exclusively."}]'::jsonb, 'c'),
  ('fg-g00714', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'What is the focus of the Integrated Social Forestry Program (ISFP) in the Philippines?',
   '[{"id":"a","text":"Promotion of monoculture plantations."},{"id":"b","text":"Development of forest-based livelihood activities and sustainable forest management."},{"id":"c","text":"Construction of dams and water reservoirs in forest areas."},{"id":"d","text":"Expansion of urban areas into forest lands."}]'::jsonb, 'b'),
  ('fg-g00715', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'Which government agency is primarily responsible for implementing social forestry programs in the Philippines?',
   '[{"id":"a","text":"Department of Agriculture (DA)"},{"id":"b","text":"Department of Public Works and Highways (DPWH)"},{"id":"c","text":"Department of Environment and Natural Resources (DENR)"},{"id":"d","text":"Department of Trade and Industry (DTI)"}]'::jsonb, 'c'),
  ('fg-g00716', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'Which of the following is a key element of the community organizing process in social forestry?',
   '[{"id":"a","text":"Imposing government mandates without community input."},{"id":"b","text":"Active participation and empowerment of local communities."},{"id":"c","text":"Top-down decision making."},{"id":"d","text":"Exclusive reliance on external experts for planning."}]'::jsonb, 'b'),
  ('fg-g00717', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'What is the purpose of a People''s Organization (PO) in the context of social forestry in the Philippines?',
   '[{"id":"a","text":"To handle all government logging operations."},{"id":"b","text":"To export timber overseas."},{"id":"c","text":"To restrict community access to forest resources."},{"id":"d","text":"To serve as a partner in managing forests sustainably."}]'::jsonb, 'd'),
  ('fg-g00718', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'What type of land tenure instrument is commonly associated with social forestry in the Philippines?',
   '[{"id":"a","text":"Community-Based Forest Management Agreement (CBFMA)"},{"id":"b","text":"Free Patent"},{"id":"c","text":"Residential Title"},{"id":"d","text":"Industrial Forest Management Agreement (IFMA)"}]'::jsonb, 'a'),
  ('fg-g00719', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'Which of the following is a typical activity included in a social forestry extension program?',
   '[{"id":"a","text":"Mining mineral resources."},{"id":"b","text":"Organizing tree planting and maintenance campaigns."},{"id":"c","text":"Developing urban infrastructure projects."},{"id":"d","text":"Clear-cutting for agricultural expansion."}]'::jsonb, 'b'),
  ('fg-g00720', 'forest-governance', 'social-forestry-extension', 'Easy', 'mock',
   'What is the primary objective of social forestry in the Philippines?',
   '[{"id":"a","text":"To increase commercial logging activities."},{"id":"b","text":"To convert forest lands into agricultural lands."},{"id":"c","text":"To provide sustainable livelihoods for local communities."},{"id":"d","text":"To promote urban development in forested areas."}]'::jsonb, 'c'),
